        uint256 _basefee,
        bytes32 _hash,
        uint64 _sequenceNumber,
        bytes32 _batcherHash,
        uint256 _l1FeeOverhead,
        uint256 _l1FeeScalar
    ) public payable {
        // The call may optionally be preceded by setup calls, but the version() rule doesn't
        // require any state setup; we simply call version() and assert its return value.

        string memory versionResult;
        bool reverted;
        try c.version() returns (string memory v) {
            versionResult = v;
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: whenever version() completes, it must return the exact string "1.0.0".
        assert(reverted || keccak256(bytes(versionResult)) == keccak256(bytes("1.0.0")));
    }

    receive() external payable {}
}

